+/// Represents a ComputeBlock: a group of ops sharing the same block_id
+struct ComputeBlock {
+  int id;                        // block_id value
+  CVPipeline::CoreType coreType; // CUBE_ONLY / VECTOR_ONLY
+  SmallVector<Operation *> ops;  // all ops in the group (in IR order)
+};
