+static bool hasTensorResult(const ComputeBlock &blk) {
+  for (Operation *op : blk.ops) {
+    for (Value result : op->getResults()) {
+      if (isa<TensorType>(result.getType())) {
+        return true;
+      }
+    }
+  }
+  return false;
+}
